 if not already_applied and not exists(select 1 from ca_migrations.applied where name='20261013115428_v2_request_preferences.sql') then
 execute $ca_body$alter table public.congregations add column settings jsonb not null default '{}';
alter table ca_private.workspace_applications add column choices jsonb not null default '{}';
create function public.submit_v2_workspace_application(p_name text,p_contact_email text,p_admin_email text,p_congregation text,p_phone text,p_authorized boolean,p_choices jsonb,p_website text default '') returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;request_id uuid;item text;begin
 if jsonb_typeof(p_choices)<>'object' or octet_length(p_choices::text)>5000 or p_choices->>'delivery' not in('digital','link','whatsapp','admin') or p_choices->>'privacy' not in('standard','private') or jsonb_typeof(p_choices->'modules')<>'array' then raise exception 'Invalid workspace choices';end if;
 for item in select jsonb_array_elements_text(p_choices->'modules') loop if item not in('people','reports','midweek','weekend','groups','imports','print','messages','setup') then raise exception 'Unknown module';end if;end loop;
 result=public.submit_workspace_application(p_name,p_contact_email,p_admin_email,p_congregation,p_phone,p_authorized,p_website);
 if result->>'reference' is not null then request_id=(result->>'reference')::uuid;update ca_private.workspace_applications set choices=p_choices||jsonb_build_object('version',2,'private_interest_only',p_choices->>'privacy'='private') where id=request_id;end if;
 return result;
end $$;
revoke all on function public.submit_v2_workspace_application(text,text,text,text,text,boolean,jsonb,text) from public,anon,authenticated;
grant execute on function public.submit_v2_workspace_application(text,text,text,text,text,boolean,jsonb,text) to anon,authenticated;
create function ca_private.v2_approved_choices() returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='approved' and old.status is distinct from 'approved' and new.cong_id is not null then update public.congregations set settings=settings||new.choices where id=new.cong_id;end if;return new;end $$;
