if nullif(p_person->>'baptized','') is not null then perform (p_person->>'baptized')::date;end if;
insert into public.publishers(id,cong_id,name,group_id,service_group,phone,address,gender) values(person_id,p_cong_id,btrim(p_person->>'name'),g.id,g.name,left(coalesce(p_person->>'phone',''),30),left(coalesce(p_person->>'address',''),2000),coalesce(p_person->>'gender','Male')) on conflict(id) do update set name=excluded.name,group_id=excluded.group_id,service_group=excluded.service_group,phone=excluded.phone,address=excluded.address,gender=excluded.gender;expected=public.get_publisher_login(p_cong_id,person_id);if coalesce(p_person->'expected_login','[]'::jsonb) is distinct from expected then raise exception 'Login changed on another device. Reopen the record before saving.' using errcode='40001';end if;perform public.set_publisher_login(p_cong_id,person_id,expected,new_email);update public.publishers set dob=case when p_person ? 'dob' then nullif(left(p_person->>'dob',300),'') else dob end,baptized=case when p_person ? 'baptized' then nullif(left(p_person->>'baptized',300),'') else baptized end,hope=case when p_person ? 'hope' then nullif(left(p_person->>'hope',300),'') else hope end,family_head_id=case when p_person ? 'familyHeadId' then nullif(left(p_person->>'familyHeadId',100),'') else family_head_id end,emergency_name=case when p_person ? 'emergencyName' then nullif(left(p_person->>'emergencyName',300),'') else emergency_name end,emergency_relationship=case when p_person ? 'emergencyRelationship' then nullif(left(p_person->>'emergencyRelationship',300),'') else emergency_relationship end,emergency_phone=case when p_person ? 'emergencyPhone' then nullif(left(p_person->>'emergencyPhone',30),'') else emergency_phone end,spiritual_status=case when p_person ? 'spiritualStatus' then nullif(left(p_person->>'spiritualStatus',300),'') else spiritual_status end,is_elder=case when p_person ? 'isElder' then coalesce((p_person->>'isElder')::boolean,false) else is_elder end,is_ms=case when p_person ? 'isMS' then coalesce((p_person->>'isMS')::boolean,false) else is_ms end,i